import re

def parse_duration(s: str) -> int:
    if not s:
        return 0

    total_seconds = 0
    # Find all matches of digits followed by h, m, or s
    matches = re.findall(r'(\d+)([hms])', s)

    for value, unit in matches:
        num = int(value)
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
```

