def wrap_text(text, width):
    if not text:
        return []
    words = text.split(' ')
    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if not word:
            continue
        if len(word) > width:
            if current_line:
                lines.append(' '.join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
        elif current_length + len(word) + (1 if current_line else 0) <= width:
            current_line.append(word)
            current_length += len(word) + (1 if current_line else 0)
        else:
            lines.append(' '.join(current_line))
            current_line = [word]
            current_length = len(word)

    if current_line:
        lines.append(' '.join(current_line))

    return lines
```

