def regex_match(s: str, p: str) -> bool:
    """
    Returns True if pattern p matches the entire string s.
    Pattern p contains letters, '.' (any one character), and '*' (zero or more of the preceding element).
    """
    m, n = len(s), len(p)

    # dp[i][j] means s[:i] matches p[:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* that can match empty string
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                # Case 1: '*' matches zero of the preceding element
                dp[i][j] = dp[i][j - 2]
                # Case 2: '*' matches one or more of the preceding element
                # Check if the preceding element matches current character in s
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]
            else:
                # Direct character match or '.' match
                if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                    dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]
