def eval_expr(s: str) -> float:
    """
    Evaluates an arithmetic expression string.
    Supports numbers, +, -, *, /, unary minus, and parentheses.
    Does not use eval or exec.
    """
    # Tokenizer
    def tokenize(expr: str):
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            c = expr[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit() or c == '.':
                j = i
                while j < n and (expr[j].isdigit() or expr[j] == '.'):
                    j += 1
                tokens.append(('NUM', float(expr[i:j])))
                i = j
            elif c in '+-*/()':
                tokens.append(('OP', c))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {c}")
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def parse(self):
            result = self.parse_expression()
            if self.pos < len(self.tokens):
                raise ValueError("Unexpected token after expression")
            return result

        def parse_expression(self):
            """Parse addition and subtraction (lowest precedence)"""
            left = self.parse_term()
            while self.peek() and self.peek()[1] in ('+', '-'):
                op = self.consume()[1]
                right = self.parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_term(self):
            """Parse multiplication and division"""
            left = self.parse_unary()
            while self.peek() and self.peek()[1] in ('*', '/'):
                op = self.consume()[1]
                right = self.parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
            return left

        def parse_unary(self):
            """Parse unary minus and numbers/parentheses"""
            if self.peek() and self.peek()[1] == '-':
                self.consume()
                operand = self.parse_unary()
                return -operand
            if self.peek() and self.peek()[1] == '+':
                self.consume()
                return self.parse_unary()
            return self.parse_primary()

        def parse_primary(self):
            """Parse numbers and parenthesized expressions"""
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of expression")

            if token[0] == 'NUM':
                self.consume()
                return token[1]

            if token[1] == '(':
                self.consume()  # consume '('
                result = self.parse_expression()
                if not self.peek() or self.peek()[1] != ')':
                    raise ValueError("Missing closing parenthesis")
                self.consume()  # consume ')'
                return result

            raise ValueError(f"Unexpected token: {token}")

    tokens = tokenize(s)
    if not tokens:
        return 0.0
    parser = Parser(tokens)
    return parser.parse()
```

