def regex_match(s: str, p: str) -> bool:
    memo = {}

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(p):
            return i == len(s)

        first_match = i < len(s) and p[j] in {s[i], '.'}

        if j + 1 < len(p) and p[j+1] == '*':
            # Case 1: Skip the '*' and its preceding element (zero occurrences)
