import re

def eval_expr(s):
    # Tokenize the string
    tokens = re.findall(r'\d+\.?\d*|[+\-*/()]', s)

    def get_precedence(op):
        if op in ('+', '-'): return 1
        if op in ('*', '/'): return 2
        return 0

    def apply_op(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+': values.append(left + right)
        elif operator == '-': values.append(left - right)
        elif operator == '*': values.append(left * right)
        elif operator == '/': values.append(left / right)

    values = []
    operators = []
    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_op(operators, values)
            operators.pop()  # Pop '('
        elif token in ('+', '-', '*', '/'):
            # Check for unary minus: if '-' is at start or follows '(' or another operator
            if token == '-' and (i == 0 or tokens[i-1] == '(' or tokens[i-1] in '+-*/'):
                # Handle unary minus by pushing a 0 to treat -x as 0-x
                values.append(0.0)

            while (operators and operators[-1] != '(' and 
                   get_precedence(operators[-1]) >= get_precedence(token)):
                apply_op(operators, values)
            operators.append(token)
        else:
            # It's a number
            values.append(float(token))
        i += 1

    while operators:
        apply_op(operators, values)

    return values[0]
