from functools import lru_cache

def regex_match(s, p):
    @lru_cache(maxsize=None)
    def dp(i, j):
        if j == len(p):
            return i == len(s)

        # Check if the current characters match
        first_match = i < len(s) and p[j] in {s[i], '.'}

        # If the next character is '*', we have two choices:
        # 1. Ignore the '*' and its preceding element (zero occurrences)
        # 2. If first_match is true, consume one character of 's' and stay at the same pattern position
        if j + 1 < len(p) and p[j+1] == '*':
            return dp(i, j + 2) or (first_match and dp(i + 1, j))
        else:
            # No '*', proceed to the next character in both string and pattern
            return first_match and dp(i + 1, j + 1)

    return dp(0, 0)
```

