import re

def eval_expr(s):
    # Tokenize the input string into numbers and operators
    tokens = re.findall(r'\d*\.?\d+|[+\-*/()]', s)
    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        # Handles addition and subtraction
        val = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                val += right
            else:
                val -= right
        return val

    def parse_term():
        # Handles multiplication and division
        val = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                val *= right
            else:
                val /= right
        return val

    def parse_factor():
        # Handles unary minus
        if peek() == '-':
            consume()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        # Handles numbers and parentheses
        token = consume()
        if token == '(':
            val = parse_expression()
            consume()  # consume ')'
            return val
        else:
            return float(token)

    return parse_expression()
