def eval_expr(s):
    s = s.strip()
    if not s:
        raise ValueError("Empty expression")

    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isspace():
            i += 1
        elif s[i] in '+-*/()':
            tokens.append(s[i])
            i += 1
        elif s[i].isdigit() or s[i] == '.':
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            tokens.append(s[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {s[i]}")

    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        res = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            res = res + right if op == '+' else res - right
        return res

    def parse_term():
        res = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            res = res * right if op == '*' else res / right
        return res

    def parse_factor():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == '(':
            consume()
            res = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume()
            return res
        elif tok == '-':
            consume()
            return -parse_factor()
        elif tok == '+':
            consume()
            return parse_factor()
        else:
            consume()
            return float(tok)

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected tokens after expression")
    return result
