import re

def eval_expr(s):
    tokens = tokenize(s)
    return parse_expression(tokens)

def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            if c == '.':
                j += 1
                while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                    j += 1
            else:
                j = i
                while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                    j += 1
            tokens.append(s[i:j])
            i = j
        else:
            i += 1
    return tokens

def parse_expression(tokens):
    def parse_term():
        def parse_factor():
            if tokens[0] == '(':
                tokens.pop(0)
                val = parse_expression(tokens)
                if tokens[0] != ')':
                    raise ValueError("Mismatched parentheses")
                tokens.pop(0)
                return val
            elif tokens[0] == '-' or tokens[0] == '+':
                sign = tokens.pop(0)
                val = parse_factor()
                return -val if sign == '-' else val
            else:
                num = tokens.pop(0)
                return float(num)
        val = parse_factor()
        while tokens and tokens[0] in '*/':
            op = tokens.pop(0)
            right = parse_factor()
            if op == '*':
                val *= right
            else:
                val /= right
        return val

    val = parse_term()
    while tokens and tokens[0] in '+-':
        op = tokens.pop(0)
        right = parse_term()
        if op == '+':
            val += right
        else:
            val -= right
    return val
```

