def eval_expr(s):
    pos = 0

    def skip():
        nonlocal pos
        while pos < len(s) and s[pos].isspace():
            pos += 1

    def peek():
        skip()
        return s[pos] if pos < len(s) else ''

    def parse_expr():
        value = parse_term()
        while True:
            c = peek()
            if c == '+':
                nonlocal pos
                pos += 1
                value = value + parse_term()
            elif c == '-':
                nonlocal pos
                pos += 1
                value = value - parse_term()
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            c = peek()
            if c == '*':
                nonlocal pos
                pos += 1
                value = value * parse_unary()
            elif c == '/':
                nonlocal pos
                pos += 1
                value = value / parse_unary()
            else:
                return value

    def parse_unary():
        c = peek()
        if c == '-':
            nonlocal pos
            pos += 1
            return -parse_unary()
        if c == '+':
            nonlocal pos
            pos += 1
            return parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        skip()
        if peek() == '(':
            pos += 1
            value = parse_expr()
            skip()
            if peek() != ')':
                raise ValueError('Expected )')
            pos += 1
            return value
        start = pos
        while pos < len(s) and (s[pos].isdigit() or s[pos] == '.'):
            pos += 1
        if start == pos:
            raise ValueError('Expected number')
        return float(s[start:pos])

    result = parse_expr()
    skip()
    if pos != len(s):
        raise ValueError('Unexpected character')
    return result
